//! Emitted A32 wasm against the interpreter on adversarial operands and memory.
//! Needs no title or keys. Encodings are generated by field, not hand-assembled,
//! so the interpreter, which is checked against `qemu-arm`, is the reference.
//!
//! ```text
//! cargo run --release --example a32_emit_selftest
//! node tools/emit_difftest.mjs --out=target/a32-emit-selftest
//! ```

mod common;

use clap::Parser;
use common::emit::{self, LAYOUT, TABLE_AT, TABLE_BYTES};
use std::fmt::Write as _;
use switch_core::cpu::{Cpu, ExecMode};

const PAGE_BYTES: u32 = 4096;
const WINDOW_PAGES: u32 = 17;
const WINDOW_BYTES: u32 = WINDOW_PAGES * PAGE_BYTES;
/// Where the mapped guest pages live, one 4 KiB slot each.
const POOL_AT: u32 = TABLE_AT + TABLE_BYTES;
const BITMAP_AT: u32 = POOL_AT + WINDOW_BYTES;
const BITMAP_BYTES: u32 = (1 << 20) / 8;
/// Slot of the `n`th window page, scattered so page-boundary checks are exercised.
/// [`WINDOW_PAGES`] is prime, so the stepping reaches every slot.
const SCATTER: u32 = 7;

/// Where the test program is mapped, inside the window.
const CODE_AT: u32 = 0x1000;
const READ_WATCH_AT: u32 = 0x2040;
const READ_WATCH_BYTES: u32 = 0x40;
const WATCH_AT: u32 = 0x20C0;
const WATCH_BYTES: u32 = 0x40;
/// A cached page; stores there must hand back.
const WATCHED_PAGE_AT: u32 = 3 * PAGE_BYTES;
const READONLY: (u32, u32) = (5 * PAGE_BYTES, 6 * PAGE_BYTES);

/// `svc #0`, which ends every block.
const SVC: u32 = 0xEF00_0000;

/// Random encodings per instruction class, and register sets each runs under.
const DATA_PROCESSING: usize = 4000;
const TRANSFERS: usize = 2500;
const EXCLUSIVE_PAIRS: usize = 600;
const BRANCHES: usize = 3000;
const THREAD_POINTER_READS: usize = 60;
const EXTENDS: usize = 600;
const BITFIELD_EXTRACTS: usize = 1500;
const MEDIA_AND_MULTIPLIES: usize = 1500;
const SEEDS: usize = 6;
/// Random VFP instructions and doubleword transfers.
const VFP: usize = 6000;
const DOUBLEWORDS: usize = 800;
/// Random Advanced SIMD data-processing and load/store instructions.
const NEON: usize = 24000;

/// Above 32 bits, so a read that fails to narrow shows.
const TPIDR_SEED: u64 = 0x1234_5678_9ABC;
const TPIDR_RW_SEED: u64 = 0x0FED_CBA9_8765;

/// What a case's block does that the emitted form has to match.
#[derive(Clone, Copy, PartialEq)]
enum Kind {
    /// Data processing only: every instruction retires.
    Pure,
    /// One memory access, which may hand back.
    Memory,
    /// A load-exclusive and a store-exclusive at the address in `rn`, whose alignment
    /// is `mask`: the module retires both or hands back neither.
    Pair { rn: usize, mask: u32 },
    /// Ends in a branch, which the module leaves through with the target in the pc.
    Branch,
}

#[derive(Parser)]
struct Cli {
    #[command(flatten)]
    shared: common::Shared,
    /// Where the modules and the manifest are written.
    #[arg(long, default_value = "target/a32-emit-selftest", value_name = "DIR")]
    out: String,
}

fn main() {
    let out_dir = common::parse::<Cli>(|cli| common::Flags::default().with(&cli.shared)).out;
    std::fs::create_dir_all(&out_dir).expect("cannot create the output directory");
    std::fs::write(format!("{out_dir}/guest.bin"), window_bytes())
        .expect("cannot write the window");

    let mut rng = 0x243F_6A88_85A3_08D3u64;
    let mut cases = Vec::new();
    for _ in 0..DATA_PROCESSING {
        // A short run of data processing shares one block, so flags and registers carry.
        let run = 1 + next(&mut rng) as usize % 5;
        let body: Vec<u32> = (0..run).map(|_| data_processing(&mut rng)).collect();
        cases.push((body, Kind::Pure));
    }
    for _ in 0..TRANSFERS {
        cases.push((vec![transfer(&mut rng)], Kind::Memory));
    }
    for _ in 0..EXTENDS {
        // SXTB, SXTH, UXTB or UXTH, rotated by 0 to 24, with Rn of 15 being the plain form.
        let r = next(&mut rng);
        let (cond, rd, rm) = (
            (r & 0xF) as u32 % 15,
            (r >> 4 & 0xF) as u32 % 15,
            (r >> 8 & 0xF) as u32 % 15,
        );
        let (rn, rotate, op) = (
            (r >> 12 & 0xF) as u32,
            (r >> 16 & 3) as u32,
            [0x6A, 0x6B, 0x6E, 0x6F][(r >> 18) as usize & 3],
        );
        cases.push((
            vec![cond << 28 | op << 20 | rn << 16 | rd << 12 | rotate << 10 | 0x70 | rm],
            Kind::Pure,
        ));
    }
    for _ in 0..MEDIA_AND_MULTIPLIES {
        // A short run, so flags and registers carry between them.
        let run = 1 + next(&mut rng) as usize % 3;
        let body: Vec<u32> = (0..run).map(|_| media_or_multiply(&mut rng)).collect();
        cases.push((body, Kind::Pure));
    }
    for _ in 0..VFP {
        // A run of non-memory instructions shares a block, so a compare's flags and a
        // register's value carry between them; a transfer is alone, as it may hand back.
        let first = vfp(&mut rng);
        if first >> 25 & 0b111 == 0b110 {
            cases.push((vec![first], Kind::Memory));
            continue;
        }
        let mut body = vec![first];
        for _ in 0..next(&mut rng) as usize % 3 {
            let insn = vfp(&mut rng);
            if insn >> 25 & 0b111 != 0b110 {
                body.push(insn);
            }
        }
        cases.push((body, Kind::Pure));
    }
    for _ in 0..NEON {
        let first = neon(&mut rng);
        if first >> 24 == 0xF4 {
            cases.push((vec![first], Kind::Memory));
            continue;
        }
        // A float result may be a NaN whose payload depends on the engine, which a later
        // integer instruction would turn into a value that differs.
        let mut body = vec![first];
        for _ in 0..if rounds(first) {
            0
        } else {
            next(&mut rng) as usize % 3
        } {
            let insn = neon(&mut rng);
            if insn >> 24 != 0xF4 && !rounds(insn) {
                body.push(insn);
            }
        }
        cases.push((body, Kind::Pure));
    }
    for _ in 0..DOUBLEWORDS {
        cases.push((vec![doubleword(&mut rng)], Kind::Memory));
    }
    for _ in 0..BITFIELD_EXTRACTS {
        // SBFX or UBFX, whose field may run past the top of the word.
        let r = next(&mut rng);
        let (cond, rd, rm) = (
            (r & 0xF) as u32 % 15,
            (r >> 4 & 0xF) as u32,
            (r >> 8 & 0xF) as u32,
        );
        let (op, lsb, width) = (
            [0x7A, 0x7B, 0x7E, 0x7F][(r >> 12) as usize & 3],
            (r >> 14 & 0x1F) as u32,
            (r >> 19 & 0x1F) as u32,
        );
        cases.push((
            vec![cond << 28 | op << 20 | width << 16 | rd << 12 | lsb << 7 | 0x50 | rm],
            Kind::Pure,
        ));
    }
    for _ in 0..THREAD_POINTER_READS {
        // MRC p15, 0, rt, c13, c0, 2 or 3.
        let r = next(&mut rng);
        let (rt, opc2) = ((r & 0xF) as u32 % 15, 2 + (r >> 4 & 1) as u32);
        cases.push((vec![0xEE1D_0F10 | rt << 12 | opc2 << 5], Kind::Pure));
    }
    for _ in 0..EXCLUSIVE_PAIRS {
        // A load that arms the monitor and a store to the same address that can succeed.
        let r = next(&mut rng);
        let (rn, dest, status, value) = (
            (r & 0xF) as u32 % 13,
            (r >> 4 & 0xF) as u32 % 13,
            (r >> 8 & 0xF) as u32 % 13,
            (r >> 12 & 0xF) as u32 % 13,
        );
        let size = [0b00, 0b10, 0b11][(r >> 16) as usize % 3] << 21;
        // A load into the base would move the store's address.
        let dest = if dest == rn { (rn + 1) % 13 } else { dest };
        let ldrex = 0xE190_0F9F | size | rn << 16 | dest << 12;
        let strex = 0xE180_0F90 | size | rn << 16 | status << 12 | value;
        cases.push((
            vec![ldrex, strex],
            Kind::Pair {
                rn: rn as usize,
                mask: [3, 0, 0, 1][(size >> 21) as usize],
            },
        ));
    }
    for _ in 0..BRANCHES {
        let end = branch(&mut rng);
        // A load into the PC may hand back, which the check only knows as all or nothing.
        let run = if loads_pc(end) {
            0
        } else {
            next(&mut rng) as usize % 3
        };
        let mut body: Vec<u32> = (0..run).map(|_| data_processing(&mut rng)).collect();
        body.push(end);
        cases.push((body, Kind::Branch));
    }

    let mut manifest = String::new();
    let (mut written, mut refused, mut faulted, mut rewrote, mut pinned, mut to_thumb) =
        (0, 0, 0, 0, 0, 0);
    for (body, kind) in &cases {
        let memory = *kind == Kind::Memory;
        let mut program = body.clone();
        program.push(SVC);
        let code = code_bytes(&program);
        let baseline = baseline(&code);
        let mut cpu = mapped_cpu(&code);
        let mut announced = false;
        for set in 0..SEEDS {
            cpu.mem.map(0, &baseline).expect("the window is mapped");
            seed(&mut cpu, set, (next(&mut rng) & 0xF) as u8);
            for i in 0..32 {
                cpu.set_vreg(i, emit::kind_seed(i, seed_kind(set)));
            }
            let fpscr = FPSCR_SEEDS[set % FPSCR_SEEDS.len()];
            cpu.set_fpscr_nzcv(fpscr.0);
            cpu.set_fpcr(fpscr.1);
            cpu.set_fpsr(fpscr.2);
            cpu.set_thread_pointers(TPIDR_SEED, TPIDR_RW_SEED);
            arm_monitor(&mut cpu, body[0], set);
            let monitor_before = cpu.exclusive_state();
            let before = cpu.reg_slots();
            let nzcv_before = cpu.nzcv();
            let Ok((module, ops)) = cpu.emit_a32_block_at(CODE_AT, LAYOUT) else {
                refused += 1;
                break;
            };

            cpu.mem.map(0, &baseline).expect("the window is mapped");
            cpu.mem.take_read_hit();
            cpu.mem.take_watch_hit();
            cpu.mem.mark_code_page(WATCHED_PAGE_AT);
            cpu.mem.dirty_code_pages(0);
            let mut fault = false;
            for _ in 0..ops {
                if cpu.step().is_err() {
                    fault = true;
                    break;
                }
            }
            if fault && !memory {
                faulted += 1;
                continue;
            }
            // An interworking branch to Thumb is the interpreter's.
            if cpu.is_thumb() {
                to_thumb += 1;
                cpu = mapped_cpu(&code);
                continue;
            }
            // A store over the block's own code leaves the interpreter running other words.
            let mut now = vec![0u8; code.len()];
            cpu.mem
                .read_into(CODE_AT, &mut now)
                .expect("the code is mapped");
            if now != code {
                rewrote += 1;
                continue;
            }
            let must_hand_back = fault
                || cpu.mem.take_read_hit().is_some()
                || cpu.mem.take_watch_hit().is_some()
                || cpu
                    .mem
                    .dirty_code_pages(0)
                    .is_none_or(|pages| !pages.is_empty());
            if let Kind::Pair { rn, mask } = kind {
                if must_hand_back || before[*rn] as u32 & mask != 0 {
                    continue;
                }
            }
            // The terminator is the last of the body when the module covers it.
            let left = *kind == Kind::Branch && ops == body.len();
            let loaded_pc = loads_pc(body[body.len() - 1]);
            let mode = match (memory, must_hand_back, left) {
                (_, true, true) if loaded_pc => {
                    pinned += 1;
                    "none".into()
                }
                (_, _, true) if loaded_pc => format!("maybe-left:{:#010x}", cpu.get_pc()),
                (_, _, true) => format!("left:{:#010x}", cpu.get_pc()),
                (false, _, false) => "exact".into(),
                (true, false, _) => "maybe".into(),
                (true, true, _) => {
                    pinned += 1;
                    "none".into()
                }
            };

            if !announced {
                manifest.push_str("code ");
                for b in &code {
                    let _ = write!(manifest, "{b:02x}");
                }
                manifest.push('\n');
                announced = true;
            }
            let name = format!("case{written:05}");
            std::fs::write(format!("{out_dir}/{name}.wasm"), &module)
                .expect("cannot write a module");
            let _ = write!(
                manifest,
                "{name} {CODE_AT:#010x} {ops} {mode} {nzcv_before:#010x} {:#010x}",
                cpu.nzcv()
            );
            for v in before {
                let _ = write!(manifest, " {v:016x}");
            }
            manifest.push_str(" |");
            for v in cpu.reg_slots() {
                let _ = write!(manifest, " {v:016x}");
            }
            manifest.push_str(" !");
            manifest.push_str(&memory_delta(&cpu, &baseline));
            manifest.push_str(&emit::vreg_delta(&cpu, |i| {
                emit::kind_seed(i, seed_kind(set))
            }));
            if let Some(kind) = seed_kind(set) {
                let _ = write!(manifest, " {kind}");
            }
            if body.iter().copied().any(rounds) {
                manifest.push_str(" nansign");
            }
            let _ = write!(
                manifest,
                " fpscr:{:x}:{:x} fpcr:{:x}:{:x} fpsr:{:x}:{:x}",
                fpscr.0,
                cpu.fpscr_nzcv(),
                fpscr.1,
                cpu.fpcr(),
                fpscr.2,
                cpu.fpsr()
            );
            let monitor_after = cpu.exclusive_state();
            let _ = write!(
                manifest,
                " excl:{:x}:{}:{:x}:{:x}:{:x}:{}:{:x}:{:x}",
                monitor_before.0,
                u8::from(monitor_before.1),
                monitor_before.2[0],
                monitor_before.2[1],
                monitor_after.0,
                u8::from(monitor_after.1),
                monitor_after.2[0],
                monitor_after.2[1],
            );
            manifest.push('\n');
            written += 1;
        }
    }

    let header = emit::header()
        + &format!(
            "bitmap_at {BITMAP_AT}\n\
             code_at {CODE_AT}\n\
             read_watch {READ_WATCH_AT} {}\n\
             watch {WATCH_AT} {}\n\
             watched_page {WATCHED_PAGE_AT} {}\n\
             tpidr_values {TPIDR_SEED} {TPIDR_RW_SEED}\n\
             wasm_pages {}\n\
             {}",
            READ_WATCH_AT + READ_WATCH_BYTES,
            WATCH_AT + WATCH_BYTES,
            READONLY.0,
            (BITMAP_AT + BITMAP_BYTES).div_ceil(64 * 1024),
            page_lines(),
        );
    std::fs::write(format!("{out_dir}/manifest.txt"), header + &manifest)
        .expect("cannot write the manifest");
    println!(
        "{written} cases written to {out_dir}/ ({pinned} where memory has to hand back, \
         {refused} blocks refused, {faulted} faulted, {to_thumb} to Thumb, {rewrote} stored over their code)"
    );
    println!("now run: node tools/emit_difftest.mjs --out={out_dir}");
}

/// FPSCR as its flags, FPCR and FPSR, per seed set.
const FPSCR_SEEDS: [(u32, u32, u32); 3] = [
    (0, 0, 0),
    (0xF000_0000, 0x07C0_0000, 0x9F),
    (0x5000_0000, 0x0040_0000, 0x10),
];

/// What the vector registers hold for a seed set besides noise.
fn seed_kind(set: usize) -> Option<&'static str> {
    match set {
        4 => Some("doubles"),
        5 => Some("infinities"),
        _ => None,
    }
}

/// Whether `insn` is VFP arithmetic or a conversion, whose result for a NaN operand has
/// a sign that neither the host's floating point nor the interpreter's compilation fixes.
fn rounds(insn: u32) -> bool {
    if insn >> 28 == 0xF && insn >> 25 & 7 == 1 {
        let opc = insn >> 8 & 0xF;
        return match (insn >> 23 & 1, insn >> 4 & 1, insn >> 20 & 3) {
            (0, _, _) => matches!(opc, 0xD..=0xF),
            (1, 0, size) if size != 3 && insn >> 6 & 1 == 1 => matches!(opc, 1 | 5 | 9),
            (1, 0, 3) if insn >> 24 & 1 == 1 => insn >> 16 & 3 == 3,
            _ => false,
        };
    }
    let data = insn >> 24 & 0xF == 0xE && insn & 0x10 == 0 && matches!(insn >> 8 & 0xF, 0xA | 0xB);
    let extended = data && insn >> 23 & 1 == 1 && insn >> 20 & 3 == 3;
    let exact = extended
        && (insn >> 6 & 1 == 0 || matches!((insn >> 16 & 0xF, insn >> 6 & 3), (0, _) | (1, 1)));
    data && !exact
}

/// A random Advanced SIMD instruction: a data-processing group with its fixed bits set
/// and the rest random, or a load or store.
fn neon(rng: &mut u64) -> u32 {
    let r = next(rng);
    let bits = (r >> 8) as u32;
    let low = r as u32;
    let d = low >> 4 & 1;
    let q = low >> 5 & 1;
    let u = low >> 6 & 1;
    let size = low >> 7 & 3;
    let vd = bits >> 4 & 0xF;
    let vn = bits >> 8 & 0xF;
    let vm = bits >> 12 & 0xF;
    let fields = d << 22 | vn << 16 | vd << 12 | vm | (low >> 9 & 1) << 7 | (low >> 10 & 1) << 5;
    match r >> 40 & 15 {
        0..=3 => {
            // Three registers of the same length.
            let opc = [0, 1, 2, 3, 6, 7, 8, 9, 0xD, 0xE, 0xF][(r >> 44) as usize % 11];
            0xF200_0000 | u << 24 | size << 20 | opc << 8 | (low >> 11 & 1) << 4 | q << 6 | fields
        }
        4 => {
            // Modified immediate.
            let cmode = low >> 11 & 0xF;
            0xF280_0010
                | u << 24
                | (low >> 15 & 7) << 16
                | cmode << 8
                | (low >> 19 & 1) << 5
                | q << 6
                | (d << 22 | vd << 12 | bits & 0xF)
        }
        5 => {
            // Shifts by an immediate.
            let opc = [0, 1, 5, 8, 0xA][(r >> 44) as usize % 5];
            let imm6 = (low >> 11 | 8) & 0x3F;
            0xF280_0010
                | u << 24
                | imm6 << 16
                | opc << 8
                | (low >> 17 & 1) << 7
                | q << 6
                | fields & !(0xF << 16 | 1 << 7)
        }
        6 => {
            // VEXT.
            0xF2B0_0000 | (low >> 11 & 0xF) << 8 | q << 6 | fields
        }
        7 | 8 => {
            // Two registers, miscellaneous, and VDUP from a lane.
            let table = low >> 11 & 3;
            let op = [0, 1, 2, 4, 5, 6, 7, 8, 9, 10, 11, 12, 14, 15][(r >> 44) as usize % 14];
            if r >> 50 & 3 == 0 {
                0xF3B0_0C00
                    | (low >> 13 & 0xF) << 16
                    | q << 6
                    | (d << 22 | vd << 12 | vm | (low >> 9 & 1) << 5)
            } else {
                0xF3B0_0000
                    | size << 18
                    | table << 16
                    | op << 7
                    | q << 6
                    | (d << 22 | vd << 12 | vm | (low >> 9 & 1) << 5)
            }
        }
        9 => {
            // Three registers of different lengths.
            let opc = [0, 1, 2, 3, 5, 7, 8, 0xA, 0xC][(r >> 44) as usize % 9];
            0xF280_0000
                | u << 24
                | (size % 3) << 20
                | opc << 8
                | fields & !(1 << 7 | 1 << 6 | 1 << 4)
                | (low >> 9 & 1) << 7
        }
        10 => {
            // By a scalar.
            let opc = [0, 1, 4, 5, 8, 9][(r >> 44) as usize % 6];
            0xF280_0040 | q << 24 | (1 + size % 2) << 20 | opc << 8 | fields
        }
        _ => {
            // Loads and stores of vector elements and structures.
            let rn = (low >> 11 & 0xF) % 15;
            let rm = [15, 13, 0, 1, 2, 5][(r >> 44) as usize % 6];
            let rm = if rm == 15 || rm == 13 { rm } else { rm % 13 };
            let load = low >> 15 & 1;
            if r >> 50 & 3 == 0 {
                // One element or lane.
                let all = r >> 52 & 1;
                let ty = if all == 1 { 0xC } else { size << 2 };
                0xF480_0000
                    | d << 22
                    | load << 21
                    | rn << 16
                    | vd << 12
                    | ty << 8
                    | (low >> 16 & 0xF) << 4
                    | rm
            } else {
                let ty = [7, 10, 6, 2, 8, 9, 3, 4, 5, 0, 1][(r >> 44) as usize % 11];
                0xF400_0000
                    | d << 22
                    | load << 21
                    | rn << 16
                    | vd << 12
                    | ty << 8
                    | size << 6
                    | (low >> 16 & 3) << 4
                    | rm
            }
        }
    }
}

/// A random LDRD or STRD, whose pair of registers is even and below r14.
fn doubleword(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = if (r >> 4) & 3 == 0 {
        (r & 0xF) as u32 % 15
    } else {
        0xE
    };
    let (pre, add, wb, store) = ((r >> 8) & 1, (r >> 9) & 1, (r >> 10) & 1, (r >> 11) & 1);
    let rn = ((r >> 12) & 0xF) as u32 % 15;
    let rt = ((r >> 16) & 0x7) as u32 * 2 % 14;
    let offset = if (r >> 20) & 1 != 0 {
        1 << 22 | ((r >> 24) as u32 & 0xF) << 8 | (r >> 28) as u32 & 0xF
    } else {
        (r >> 24) as u32 & 0xF
    };
    cond << 28
        | (pre as u32) << 24
        | (add as u32) << 23
        | (wb as u32) << 21
        | rn << 16
        | rt << 12
        | offset
        | 0x90
        | (0b10 + store as u32) << 5
}

/// A random VFP instruction of any shape the interpreter has: arithmetic, the one-operand
/// group, loads and stores, and the transfers to and from core registers.
fn vfp(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = if (r >> 4) & 3 == 0 {
        (r & 0xF) as u32 % 15
    } else {
        0xE
    };
    let double = (r >> 8 & 1) as u32;
    let sz = 0xA | double;
    let reg = |shift: u32| (r >> shift & 0xF) as u32;
    let bit = |shift: u32| (r >> shift & 1) as u32;
    let rt = (r >> 40 & 0xF) as u32 % 15;
    let base = cond << 28;
    match (r >> 12) % 9 {
        0 => {
            // Arithmetic: VMLA, VNMLA, VMUL, VADD, VDIV and their fused cousins.
            let (p, qr) =
                [(0, 0), (0, 1), (0, 2), (0, 3), (1, 0), (1, 1), (1, 2)][(r >> 16) as usize % 7];
            base | 0xE << 24
                | p << 23
                | bit(20) << 22
                | qr << 20
                | reg(24) << 16
                | reg(28) << 12
                | sz << 8
                | bit(32) << 7
                | bit(33) << 6
                | bit(34) << 5
                | reg(36)
        }
        1 => {
            // The one-operand group: moves, absolute value, negation, square root, compares,
            // conversions.
            let (opc2, opc3) = [
                (0, 1),
                (0, 3),
                (1, 1),
                (1, 3),
                (4, 1),
                (4, 3),
                (5, 1),
                (5, 3),
                (7, 3),
                (8, 1),
                (8, 3),
                (12, 1),
                (12, 3),
                (13, 1),
                (13, 3),
                (10, 1),
                (2, 3),
            ][(r >> 16) as usize % 17];
            base | 0xEB << 20
                | bit(20) << 22
                | opc2 << 16
                | reg(24) << 12
                | sz << 8
                | opc3 << 6
                | bit(34) << 5
                | reg(36)
        }
        2 => {
            // VMOV immediate.
            base | 0xEB << 20
                | bit(20) << 22
                | reg(24) << 16
                | reg(28) << 12
                | sz << 8
                | bit(34) << 5
                | reg(36)
        }
        3 => {
            // VLDR and VSTR.
            let rn = if r >> 48 & 7 == 0 {
                15
            } else {
                (r >> 44 & 0xF) as u32 % 15
            };
            base | 0xD << 24
                | bit(20) << 23
                | bit(21) << 22
                | bit(22) << 20
                | rn << 16
                | reg(24) << 12
                | sz << 8
                | (r >> 28 & 0x3F) as u32
        }
        4 => {
            // VLDM, VSTM, VPUSH and VPOP.
            let (p, u, w) = [(0, 1, 0), (0, 1, 1), (1, 0, 1)][(r >> 16) as usize % 3];
            let rn = (r >> 44 & 0xF) as u32 % 15;
            let words = 1 + (r >> 24) as u32 % 12;
            base | 0b110 << 25
                | p << 24
                | u << 23
                | bit(20) << 22
                | w << 21
                | bit(21) << 20
                | rn << 16
                | reg(28) << 12
                | sz << 8
                | (words * (1 + double)) & 0xFF
        }
        5 => {
            // VMOV between two core registers and a D register or two S registers.
            let rt2 = (r >> 44 & 0xF) as u32 % 15;
            base | 0xC4 << 20
                | bit(20) << 20
                | rt2 << 16
                | rt << 12
                | sz << 8
                | bit(34) << 5
                | 1 << 4
                | reg(36)
        }
        6 => {
            // VMOV between a single register and a core register.
            base | 0xE0 << 20
                | bit(20) << 20
                | reg(24) << 16
                | rt << 12
                | 0xA << 8
                | bit(34) << 7
                | 1 << 4
        }
        7 => {
            // VMRS and VMSR, with APSR_nzcv as the destination of a quarter of the reads.
            let rt = if bit(20) == 1 && r >> 22 & 3 == 0 {
                15
            } else {
                rt
            };
            base | 0xEE << 20 | 0xA10 | bit(20) << 20 | rt << 12 | 1 << 16
        }
        _ => {
            if bit(20) == 1 {
                // VDUP from a core register.
                base | 0xE8 << 20
                    | bit(21) << 22
                    | bit(22) << 21
                    | reg(24) << 16
                    | rt << 12
                    | 0xB << 8
                    | bit(34) << 7
                    | bit(35) << 5
                    | 1 << 4
            } else {
                // VMOV between a core register and a lane of a D register.
                base | 0xE0 << 20
                    | bit(21) << 23
                    | ((r >> 22 & 3) as u32) << 21
                    | bit(23) << 20
                    | reg(24) << 16
                    | rt << 12
                    | 0xB << 8
                    | bit(34) << 7
                    | ((r >> 35 & 3) as u32) << 5
                    | 1 << 4
            }
        }
    }
}

/// A random `SXTB16`/`UXTB16`, `BFI`/`BFC`, multiply or data-processing instruction
/// shifted by a register, none of which writes the PC.
fn media_or_multiply(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = (r & 0xF) as u32 % 15;
    let (a, b, c, d) = (
        (r >> 4 & 0xF) as u32,
        (r >> 8 & 0xF) as u32,
        (r >> 12 & 0xF) as u32,
        (r >> 16 & 0xF) as u32,
    );
    let not_pc = |n: u32| n % 15;
    match r >> 20 & 3 {
        0 => {
            // SXTB16 or UXTB16, the plain form when Rn is 15.
            let op = [0x68, 0x6C][(r >> 22 & 1) as usize];
            cond << 28
                | op << 20
                | a << 16
                | not_pc(b) << 12
                | u32::from((r >> 23 & 3) as u8) << 10
                | 0x70
                | not_pc(c)
        }
        1 => {
            // BFI, or BFC when Rn is 15.
            let lsb = (r >> 24 & 0x1F) as u32;
            let msb = lsb + (r >> 29 & 0x1F) as u32 % (32 - lsb);
            cond << 28 | 0x7C << 20 | msb << 16 | not_pc(b) << 12 | lsb << 7 | 0x10 | a
        }
        2 => {
            // MUL, MLA, MLS, UMULL, UMLAL, SMULL or SMLAL, with or without S.
            let op = [0, 1, 3, 4, 5, 6, 7][(r >> 24) as usize % 7];
            let s = if op == 3 { 0 } else { (r >> 28 & 1) as u32 };
            cond << 28
                | op << 21
                | s << 20
                | not_pc(a) << 16
                | not_pc(b) << 12
                | not_pc(c) << 8
                | 0x90
                | not_pc(d)
        }
        _ => {
            // A data-processing opcode with its second operand shifted by a register.
            let opcode = (r >> 24 & 0xF) as u32;
            let compare = (8..=11).contains(&opcode);
            let s = compare || r >> 28 & 1 != 0;
            let rd = not_pc(b);
            let ty = (r >> 29 & 3) as u32;
            cond << 28
                | opcode << 21
                | u32::from(s) << 20
                | a << 16
                | rd << 12
                | c << 8
                | ty << 5
                | 0x10
                | d
        }
    }
}

/// A random data-processing instruction with no register-specified shift, which
/// writes no PC. Every condition, opcode, shift and immediate shape.
fn data_processing(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = (r & 0xF) as u32 % 15;
    let opcode = ((r >> 4) & 0xF) as u32;
    let compare = (8..=11).contains(&opcode);
    let set_flags = compare || (r >> 8) & 1 != 0;
    let rn = ((r >> 9) & 0xF) as u32;
    let rd = ((r >> 13) & 0xF) as u32 % 15;
    if (r >> 50) & 7 == 0 {
        // MOVW or MOVT.
        let top = ((r >> 53) & 1) as u32;
        return cond << 28
            | 0x30 << 20
            | top << 22
            | (((r >> 24) & 0xF) as u32) << 16
            | rd << 12
            | (r >> 32) as u32 & 0xFFF;
    }
    let operand = if (r >> 17) & 1 != 0 {
        // A rotated immediate; a quarter of them unrotated.
        let rotate = if (r >> 18) & 3 == 0 {
            0
        } else {
            ((r >> 20) & 0xF) as u32
        };
        1 << 25 | rotate << 8 | ((r >> 24) & 0xFF) as u32
    } else {
        let rm = ((r >> 32) & 0xF) as u32;
        let ty = ((r >> 36) & 3) as u32;
        // Shifts of 0, 1, 31 and anything else, so the zero and 32 cases come up.
        let amount = match (r >> 38) & 3 {
            0 => 0,
            1 => 1,
            2 => 31,
            _ => ((r >> 40) & 0x1F) as u32,
        };
        amount << 7 | ty << 5 | rm
    };
    cond << 28 | opcode << 21 | u32::from(set_flags) << 20 | rn << 16 | rd << 12 | operand
}

/// A random `B`, `BL` or `BX`, conditional a third of the time.
fn branch(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = if r.is_multiple_of(3) {
        (r >> 4) as u32 % 15
    } else {
        0xE
    };
    let rm = (r >> 10) as u32 & 0xF;
    if (r >> 8) & 3 == 0 {
        cond << 28 | 0x012F_FF10 | rm
    } else if (r >> 8) & 3 == 1 && rm != 15 {
        cond << 28 | 0x012F_FF30 | rm
    } else if (r >> 8) & 3 == 2 {
        pc_load(cond, r >> 14)
    } else {
        // The offset is in words and signed.
        cond << 28 | 0b101 << 25 | ((r >> 9) as u32 & 1) << 24 | (r >> 12) as u32 & 0x00FF_FFFF
    }
}

/// Whether `insn` is a load that writes the PC.
fn loads_pc(insn: u32) -> bool {
    insn >> 28 != 0xF && insn >> 26 & 0b11 == 0b01 && insn >> 20 & 1 == 1 && insn >> 12 & 0xF == 15
        || insn >> 25 & 0b111 == 0b100 && insn >> 20 & 1 == 1 && insn >> 15 & 1 == 1
}

/// Arm the monitor for a store-exclusive at the address its base register holds: not at
/// all, with what memory holds, or with something else, by seed set.
fn arm_monitor(cpu: &mut Cpu, insn: u32, set: usize) {
    let store = insn & 0x0F90_00F0 == 0x0180_0090 && (insn >> 8) & 0b11 != 0;
    let addr = cpu.reg_slots()[(insn >> 16) as usize & 0xF] as u32;
    let held = match (insn >> 21) & 0b11 {
        0b10 => cpu.mem.read_u8(addr).map(u32::from),
        0b11 => cpu.mem.read_u16(addr).map(u32::from),
        _ => cpu.mem.read_u32(addr),
    };
    match held {
        Ok(held) if store && !set.is_multiple_of(3) => {
            let value = if set % 3 == 1 { held } else { held ^ 1 };
            cpu.set_exclusive(true, addr, [u64::from(value), 0]);
        }
        _ => cpu.set_exclusive(false, 0, [0, 0]),
    }
}

/// A random `LDR pc, [..]` or `LDM` that loads the PC.
fn pc_load(cond: u32, r: u64) -> u32 {
    let (pre, add) = ((r & 1) as u32, (r >> 1 & 1) as u32);
    let rn = (r >> 4 & 0xF) as u32;
    if r >> 2 & 1 == 0 {
        // The pre-indexed form may write back; the post-indexed one always does.
        let wb = if rn == 15 { 0 } else { (r >> 3 & 1) as u32 };
        let pre = if rn == 15 { 1 } else { pre };
        let offset = if r >> 8 & 1 == 0 {
            (r >> 9) as u32 & 0xFFF
        } else {
            1 << 25 | (r >> 9) as u32 & 0xFFF & !0x10 & !0xF | ((r >> 21) as u32 & 0xE)
        };
        cond << 28
            | 0b01 << 26
            | pre << 24
            | add << 23
            | wb << 21
            | 1 << 20
            | rn << 16
            | 15 << 12
            | offset
    } else {
        let wb = if rn == 15 { 0 } else { (r >> 3 & 1) as u32 };
        let list = (r >> 8) as u32 & 0x7FFF | 1 << 15;
        cond << 28 | 0b100 << 25 | pre << 24 | add << 23 | wb << 21 | 1 << 20 | rn << 16 | list
    }
}

/// A random load or store: single, extra or block.
fn transfer(rng: &mut u64) -> u32 {
    let r = next(rng);
    let cond = if (r >> 4) & 3 == 0 {
        (r & 0xF) as u32 % 15
    } else {
        0xE
    };
    let (pre, add, wb, load) = ((r >> 8) & 1, (r >> 9) & 1, (r >> 10) & 1, (r >> 11) & 1);
    let rn = ((r >> 12) & 0xF) as u32 % 15;
    let rt = ((r >> 16) & 0xF) as u32 % 15;
    let low = r >> 24;
    if (r >> 22) & 0xF == 0 {
        // LDREX{,B,H} and STREX{,B,H}, with the acquire and release forms among them.
        let size = [0b00, 0b10, 0b11][(r >> 26) as usize % 3];
        let monitor = [0xF, 0xF, 0xE, 0xC][(r >> 28) as usize % 4];
        let low = if load == 1 {
            0xF
        } else {
            (r >> 30) as u32 % 15
        };
        return cond << 28
            | 0x0180_0090
            | size << 21
            | (load as u32) << 20
            | rn << 16
            | rt << 12
            | monitor << 8
            | low;
    }
    let flags = (pre as u32) << 24 | (add as u32) << 23 | (wb as u32) << 21 | (load as u32) << 20;
    match (r >> 20) & 3 {
        0 => {
            // LDR, STR, LDRB, STRB, immediate or shifted register offset.
            let byte = ((r >> 22) & 1) as u32;
            let offset = if (r >> 23) & 1 != 0 {
                1 << 25
                    | (low as u32 & 0x1F) << 7
                    | ((low >> 5) as u32 & 3) << 5
                    | ((low >> 8) as u32 & 0xF)
            } else {
                match (low >> 8) & 3 {
                    0 => 0,
                    1 => 4,
                    _ => low as u32 & 0xFFF,
                }
            };
            cond << 28 | 0b01 << 26 | flags | byte << 22 | rn << 16 | rt << 12 | offset
        }
        1 | 2 => {
            // LDRH, STRH, LDRSB, LDRSH.
            let sh = if load == 1 {
                1 + (low as u32 & 3) % 3
            } else {
                1
            };
            let offset = if (r >> 22) & 1 != 0 {
                1 << 22 | ((low as u32 >> 2) & 0xF) << 8 | (low as u32 >> 6 & 0xF)
            } else {
                (low as u32 >> 6) & 0xF
            };
            cond << 28 | flags | rn << 16 | rt << 12 | offset & !0x90 | 0x90 | sh << 5
        }
        _ => {
            // LDM and STM, whose list reaches r15 only in a store.
            let mut list = (low as u32 & 0xFFFF) | 1 << (low as u32 >> 16 & 0xF);
            if load == 1 {
                list &= 0x7FFF;
            }
            cond << 28 | 0b100 << 25 | flags | rn << 16 | list
        }
    }
}

fn splitmix(mut z: u64) -> u64 {
    z = z.wrapping_add(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

fn next(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    splitmix(*state)
}

/// Register `i` under set `set`: pointers into the window, page edges, and
/// values at the shifter's and the adder's edges. Always 32 bits.
fn seed_value(set: usize, i: u64) -> u64 {
    match set {
        0 => 0x2000 + splitmix(i) % 0x8000,
        1 => (1 + i % 15) * u64::from(PAGE_BYTES) - i % 5,
        2 => [0, 1, 0x7FFF_FFFF, 0x8000_0000, 0xFFFF_FFFF, 31, 32, 33][(i % 8) as usize],
        3 => splitmix(0x9E37_79B9_7F4A_7C15 ^ i) & 0xFFFF_FFFF,
        4 => 0x4000 + (i * 0x100) % 0x4000,
        _ => [0x8000_0000, 0xFFFF_FFFF, 0, 0x7FFF_FFFF][(i % 4) as usize] ^ i,
    }
}

fn seed(cpu: &mut Cpu, set: usize, nzcv: u8) {
    for i in 0..15u8 {
        cpu.set_reg(i, seed_value(set, u64::from(i)) & 0xFFFF_FFFF);
    }
    cpu.set_nzcv(u32::from(nzcv) << 28);
    cpu.set_pc(CODE_AT);
}

fn pool_slot(page: u32) -> u32 {
    (page * SCATTER) % WINDOW_PAGES
}

fn pattern(a: u32) -> u8 {
    (splitmix(u64::from(a) ^ 0xA5A5_5A5A_1234_4321) >> 27) as u8
}

fn window_bytes() -> Vec<u8> {
    (0..WINDOW_BYTES).map(pattern).collect()
}

/// Where each window page goes, in `guest.bin` order.
fn page_lines() -> String {
    let mut out = String::new();
    for page in 0..WINDOW_PAGES {
        let _ = writeln!(
            out,
            "page {} {}",
            page * PAGE_BYTES,
            POOL_AT + pool_slot(page) * PAGE_BYTES
        );
    }
    out
}

fn code_bytes(program: &[u32]) -> Vec<u8> {
    program.iter().flat_map(|w| w.to_le_bytes()).collect()
}

/// An A32 `Cpu` with the window mapped and filled, `code` loaded and the watchpoints armed.
fn mapped_cpu(code: &[u8]) -> Cpu {
    let mut cpu = common::new_cpu();
    cpu.set_mode(ExecMode::A32);
    cpu.mem
        .map_zero(0, WINDOW_BYTES as usize)
        .expect("cannot map the guest window");
    cpu.mem
        .write_bytes(0, &window_bytes())
        .expect("cannot fill the guest window");
    cpu.mem.map(CODE_AT, code).expect("cannot write the code");
    cpu.mem.mark_readonly(READONLY.0, READONLY.1);
    cpu.mem.watch_reads(READ_WATCH_AT, READ_WATCH_BYTES);
    cpu.mem.watch_writes(WATCH_AT, WATCH_BYTES);
    cpu
}

/// The window as a case starts: the shared pattern with this body's code.
fn baseline(code: &[u8]) -> Vec<u8> {
    let mut out = window_bytes();
    out[CODE_AT as usize..CODE_AT as usize + code.len()].copy_from_slice(code);
    out
}

/// The window bytes the block changed, as `offset:hex` runs.
fn memory_delta(cpu: &Cpu, baseline: &[u8]) -> String {
    let mut now = vec![0u8; WINDOW_BYTES as usize];
    cpu.mem
        .read_into(0, &mut now)
        .expect("the window is mapped");
    let mut out = String::new();
    let mut at = 0usize;
    while at < now.len() {
        if now[at] == baseline[at] {
            at += 1;
            continue;
        }
        let start = at;
        while at < now.len() && now[at] != baseline[at] {
            at += 1;
        }
        let _ = write!(out, " {start}:");
        for b in &now[start..at] {
            let _ = write!(out, "{b:02x}");
        }
    }
    out
}
